[
  {
    "title": "The Competition Complexity of Auctions",
    "year": "2015",
    "description": "This paper introduces and analyzes competition complexity for multi-item auctions. It shows that for independent regular item distributions with \(m \ge 4\), the single-bidder competition complexity of the grand-bundle auction is infinite: no finite number of additional bidders guarantees that the grand-bundle auction achieves the optimal single-bidder revenue.",
    "link": "https://arxiv.org/abs/1508.07881"
  }
]
